	"dm_japanese_law_how_we_keep_you_safe_body": "Системы X проверяют отправленные ссылки на предмет спама, а также оскорбительного и запрещенного контента. Кроме того, мы анализируем особенности использования сервиса, чтобы выявлять подозрительные действия и улучшать X. Мы можем рассматривать отдельные личные сообщения в рамках расследования нарушений и случаев злоупотребления нашим сервисом, в связи с которыми мы получили жалобы, а также в целях соблюдения законов и выполнения правительственных запросов. Дополнительные сведения приведены здесь: %1$s.",
