	"gift_premium_terms_footer": "Стоимость подарочной подписки списывается в момент осуществления покупки и возврату не подлежит. Это однократная подписка, которая не подлежит замене, не объединяется с другими предложениями и не имеет денежной стоимости. Срок ее действия начнется после выполнения X проверки и присвоения этой подписки получателю, который должен будет принять наши %1$s и политики. Если получатель не отвечает каким-либо требованиям для пользования этой подпиской, отменит ее или отклонит наши условия и политики, возврат или возмещение стоимости этого подарка не предусмотрены. Может потребоваться оплата налогов. Условия могут изменяться. %2$s",
