	"golive__tip_broadcaster_1": "<b>СОВЕТ.</b> Спасибо, что начали прямую трансляцию. Поприветствуйте пользователей, которые присоединились к ней.",
	"golive__tip_broadcaster_10": "<b>СОВЕТ.</b> Спасибо, что вышли в прямой эфир в X! <3",
	"golive__tip_broadcaster_2": "<b>СОВЕТ.</b> Обращайтесь к пользователям, которые присоединяются к вашей трансляции, по имени. Им будет приятно.",
	"golive__tip_broadcaster_3": "<b>СОВЕТ.</b> Оставайтесь в прямом эфире как минимум несколько минут, чтобы другие пользователи могли найти вас.",
	"golive__tip_broadcaster_4": "<b>СОВЕТ.</b> Спросите зрителей, откуда они. Это хороший способ начать общение.",
	"golive__tip_broadcaster_5": "<b>СОВЕТ.</b> Благодарите пользователей, присоединившихся к вашей трансляции. Отвечайте на комментарии, чтобы удержать внимание аудитории.",
	"golive__tip_broadcaster_6": "<b>СОВЕТ.</b> Если во время прямого эфира пропадет сигнал, найдите другое место, где он более мощный.",
	"golive__tip_broadcaster_7": "<b>СОВЕТ.</b> Попросите пользователей начать читать вас. Тогда они смогут получать уведомления о ваших прямых эфирах.",
	"golive__tip_broadcaster_8": "<b>СОВЕТ.</b> Начните трансляцию с приветствия. Вашим зрителям это понравится.",
	"golive__tip_broadcaster_9": "<b>СОВЕТ.</b> Прежде чем завершить трансляцию, поблагодарите пользователей за то, что они посмотрели ее.",
	"golive__tip_pre_broadcast_1": "<b>СОВЕТ.</b> Перед началом прямого эфира укажите название трансляции. Это поможет другим пользователям найти ее.",
	"golive__tip_pre_broadcast_2": "<b>СОВЕТ.</b> Описательный заголовок поможет людям понять, о чем ваша трансляция.",
	"golive__tip_pre_broadcast_3": "<b>СОВЕТ.</b> Подсказать тему эфира? Проведите экскурсию, расскажите о том, что вы умеете, или о том, что вам интересно.",
	"golive__tip_pre_broadcast_4": "<b>СОВЕТ.</b> Перед выходом в прямой эфир проверьте мощность сигнала.",
	"golive__tip_pre_broadcast_5": "<b>СОВЕТ.</b> Добавьте в заголовок хэштег, чтобы пользователи могли найти вашу прямую трансляцию.",
	"golive__tip_pre_broadcast_6": "<b>СОВЕТ.</b> Пока это все советы, которые у нас есть. Спасибо, что вышли в прямой эфир в X!",
	"google_disclaimer": "Информация об адресе передается компании Google. Подробнее см. в {{}}Условиях предоставления услуг Google Maps{{}} и {{}}Политике конфиденциальности Google{{}}.",
