	"identity_description": "Отправьте свое удостоверение личности государственного образца на проверку, чтобы подтвердить личность и получить доступ к функциям, предназначенным для подписчиков Premium.",
	"identity_education_camera_permissions": "Для подтверждения вашей личности нам необходим доступ к вашей камере",
	"identity_education_cancel": "Не сейчас",
	"identity_education_conditions": "Я разрешаю X и Au10tix использовать изображения моего удостоверения личности и мое селфи, в том числе извлеченные из них биометрические данные, с целью подтверждения моей личности и обеспечения безопасности X, в частности для защиты от самозванцев. Au10tix может хранить такие данные до 30 дней. {{}}Подробнее{{}}",
	"identity_education_conditions_age_verification": "Я разрешаю X и Persona использовать изображения моего удостоверения личности и мою фотографию для проверки моего возраста. Фотография не будет сохранена. X и xAI могут сохранять информацию о возрасте. {{}}Подробнее{{}}",
	"identity_education_conditions_eea": "\"Я разрешаю X передавать компании Au10tix изображения моего удостоверения личности, в том числе биометрические данные, а также персональные данные из моего профиля с целью проверки личности.\nЯ также разрешаю X хранить изображения моего удостоверения личности, в том числе биометрические данные, в течение 30 дней и использовать их наряду с данными из моего профиля для обеспечения безопасности, в частности для защиты от самозванцев. {{}}Подробнее{{}}\"",
	"identity_education_conditions_persona_vendor": "Я разрешаю X и Persona использовать изображения моего удостоверения личности и мое селфи, в том числе извлеченные из них биометрические данные, для подтверждения моей личности, а также в целях обеспечения безопасности X, предотвращения мошенничества и проведения оплаты. Persona может хранить такие данные до 30 дней. X может хранить мое полное имя, адрес и захешированный номер удостоверения личности в течение всего срока моей подписки на сервис X Premium. {{}}Подробнее{{}}",
	"identity_education_description": "Что вам понадобится:",
