	"payment_funds_insurance_footer_secondary_text": "Дополнительные сведения о страховании FDIC и категориях владения счетами см. ﻿здесь﻿.",
	"payment_funds_insurance_footer_text": "Ваши депозиты хранятся в Cross River Bank (член FDIC) и застрахованы FDIC на сумму до 250 000 долл. США на одно физическое и одно юридическое лицо для всех открытых в банке счетов в каждой категории владения счетами (в совокупности), включая счета, открытые в представительском качестве.",
	"payment_funds_insurance_footer_text_format": "Ваши депозиты хранятся в банке Cross River («Банк»), являющемся членом FDIC, и застрахованы FDIC на сумму до {amount} долл. США на одно физическое и одно юридическое лицо для всех открытых в Банке счетов в каждой категории владения счетами (в совокупности), включая счета, открытые в представительском качестве.",
	"payment_funds_insurance_sweep_disclaimer": "Депозиты хранятся в банке Cross River, который является членом FDIC, и ﻿других учреждениях, застрахованных FDIC﻿. Для применения сквозного страхования депозитов должны быть выполнены ﻿определенные условия﻿. X Payments LLC не является банком, застрахованным FDIC. Страхование депозитов распространяется только на случаи банкротства застрахованных банков.",
	"payment_funds_insurance_sweep_presentation": "Ваши депозиты автоматически регистрируются в программе X Cash Sweep, обеспечивающей доступ к совокупному страховому покрытию от FDIC на сумму до 10 млн долл. США (с учетом определенных ограничений). ﻿Подробнее",
