	"ps__tip_broadcaster_1": "<b>СОВЕТ.</b> Благодарим вас за трансляцию! Не забудьте поприветствовать присоединившихся зрителей.",
	"ps__tip_broadcaster_11": "<b>СОВЕТ.</b> Благодарим вас за трансляцию в Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>СОВЕТ.</b> Приветствуйте присоединившихся зрителей по имени. Это им очень понравится.",
	"ps__tip_broadcaster_3": "<b>СОВЕТ.</b> Трансляция должна продолжаться как минимум несколько минут. Это поможет людям найти ее.",
	"ps__tip_broadcaster_4": "<b>СОВЕТ.</b> Спросите зрителей, откуда они. Это хороший способ начать общение.",
	"ps__tip_broadcaster_5": "<b>СОВЕТ.</b> Поблагодарите зрителей за подключение к трансляции и ответьте на комментарии, чтобы наладить взаимодействие с ними.",
	"ps__tip_broadcaster_6": "<b>СОВЕТ.</b> Если во время трансляции пропадет подключение к Интернету, перейдите в место с лучшим сигналом.",
	"ps__tip_broadcaster_7": "<b>СОВЕТ.</b> Предложите зрителям начать читать вас. Так они будут получать уведомления, когда вы выходите в прямой эфир.",
	"ps__tip_broadcaster_8": "<b>СОВЕТ.</b> Поприветствуйте зрителей сразу после начала трансляции. Это понравится пользователям, которые будут смотреть запись.",
	"ps__tip_broadcaster_9": "<b>СОВЕТ.</b> Перед завершением трансляции поблагодарите зрителей.",
	"ps__tip_pre_broadcast_1": "<b>СОВЕТ.</b> Напишите заголовок перед началом трансляции. Это поможет вам познакомиться с людьми со схожими интересами.",
	"ps__tip_pre_broadcast_2": "<b>СОВЕТ.</b> Описательный заголовок даст людям понять, о чем ваша трансляция.",
	"ps__tip_pre_broadcast_3": "<b>СОВЕТ.</b> Нужны новые идеи? Проведите экскурсию, поделитесь своими талантами или поговорите на интересующую вас тему.",
	"ps__tip_pre_broadcast_4": "<b>СОВЕТ.</b> Перед началом прямого эфира проверьте качество сигнала связи.",
	"ps__tip_pre_broadcast_5": "<b>СОВЕТ.</b> Делитесь своими трансляциями в X, чтобы охватить больше зрителей.",
	"ps__tip_pre_broadcast_6": "<b>СОВЕТ.</b> Для тех пользователей, которых вы читаете и которые читают вас, можно проводить закрытые трансляции.",
	"ps__tip_pre_broadcast_8": "<b>СОВЕТ.</b> Добавьте в название соответствующий хэштег. Это поможет людям найти вашу трансляцию.",
	"ps__tip_pre_broadcast_9": "<b>СОВЕТ.</b> Пока это все советы. Благодарим за использование Periscope!",
	"ps__tip_viewer_1": "<b>СОВЕТ.</b> Вы присоединились к трансляции в числе первых. Напишите комментарий и поприветствуйте участников.",
	"ps__tip_viewer_2": "<b>СОВЕТ:</b> Напишите комментарий чтобы <b>%1$s</b> знал(а), что вы здесь!",
	"ps__tip_viewer_3": "<b>СОВЕТ.</b> Сообщите пользователю <b>%1$s</b>, где вы смотрите трансляцию.",
	"ps__tip_viewer_4": "<b>СОВЕТ:</b> Поприветствуйте <b>%1$s</b> и других зрителей.",
