	"room_settings_clips_description": "\"Аудиоклипы содержат запись последних 30 секунд разговора. \n \nВедущие могут удалять аудиоклипы, созданные другими участниками их Аудиокомнат. Но если вы удалите один аудиоклип, то все остальные аудиоклипы, созданные в вашей Аудиокомнате, также будут удалены. \n \nЕсли вы запишете Аудиокомнату, а затем удалите запись, это также приведет к удалению всех ее аудиоклипов. \n \nАудиоклипы хранятся 30 дней.\"",
