	"tipjar_input_rationale_bitcoin": "Люди будут отправлять платежи на адрес Bitcoin, который вы указали выше.",
	"tipjar_input_rationale_kakao_pay": "\"Люди будут отправлять вам чаевые, используя QR-ссылку, которую вы предоставили выше.\nУказывая эту QR-ссылку и принимая чаевые, вы раскрываете информацию о себе, доступную в платежном сервисе, включая ваше имя, адрес электронной почты и т. д.\n\nЧтобы получить QR-ссылку Kakao Pay, в приложении KakaoTalk нажмите нажмите «Еще» > значок сканера в правом верхнем углу > денежный код > значок буфера обмена. Скопировав ссылку, вставьте ее на этой странице.\"",
